// Basic value deduction
auto value = 10;                // int
const auto PI = 3.14159;        // const double

// Complex container iteration
std::vector<std::string> names;
auto it = names.begin();        // std::vector<std::string>::iterator

// Efficient range-based iteration
for (const auto& name : names) { /* avoids copy */ }

// Function return type deduction (C++14)
auto calculate(double x) {
    return x * 2.0;             // returns double
}

// Deduction in lambda expression capture
int offset = 5;
auto summer = [offset](int x) {
    return x + offset;
};
